from typing import Tuple

Triple = Tuple[int, int, int]
Pair = Tuple[int, int]


def euclid_triple(m: int, n: int) -> Triple:
    return (m * m - n * n, 2 * m * n, m * m + n * n)


def berggren_fwd(branch: str, a: int, b: int, c: int) -> Triple:
    if branch == "A":
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if branch == "B":
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def param_map(branch: str, m: int, n: int) -> Pair:
    if branch == "A":
        return (2 * m - n, m)
    if branch == "B":
        return (2 * m + n, m)
    return (m + 2 * n, n)


def verify_lift(m: int, n: int) -> bool:
    """Check berggrenFwd_b(q(m,n)) == q(paramMap_b(m,n)) for all three branches."""
    a, b, c = euclid_triple(m, n)
    for br in ("A", "B", "C"):
        if berggren_fwd(br, a, b, c) != euclid_triple(*param_map(br, m, n)):
            return False
    return True

